package com.aivle.backend.pipeline.planning;
import static org.assertj.core.api.Assertions.assertThat;import com.aivle.backend.pipeline.integration.domain.*;import com.aivle.backend.pipeline.planning.application.MeaningfulPlanningLabel;import com.aivle.backend.pipeline.planning.domain.PlanningChangeDecision;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import tools.jackson.databind.ObjectMapper;
class MeaningfulPlanningLabelTests{@Test void labelsPriceAndChannelChangeByMeaning(){var p=PlanningChangeProposal.pending("p","r",1L,"가격과 채널을 조정하기","[\"pricing\",\"channels\"]","{}","{}","근거","[]","[]");var d=PlanningChangeDecision.decide("p",1L,ProposalDecisionStatus.ADOPT,null,1L,Instant.EPOCH);assertThat(new MeaningfulPlanningLabel(new ObjectMapper()).create(List.of(p),Map.of("p",d))).isEqualTo("시장분석 반영안 — 가격·채널 조정");}}
